    """ Recursive function to count the number of nested parentheses for a given input string
    For eg. '((()))' has three levels of nesting while '()()' has two.
    >>> deep_count('(()()) ((())) () ((())()())')
    4
    """
    count = 0
    if paren_string[0] == '(' and paren_string[-1] == ')':
        if len(paren_string) == 2:
            return 1
        count = 1 + deep_count(paren_string[1:-1])
        return count
    if paren_string[0] == '(':
        return 1 + deep_count(paren_string[1:])
    if paren_string[-1] == ')':
        return 1 + deep_count(paren_string[:-1])


