        return 1
    else:
        return compute_fibonacci(n-1) + compute_fibonacci(n-2)


def list_even_integers(num: int) -> list:
    """ Given a positive integer n, it generates a list of integers
    which contains all the even integers between 0 and n, including
    both 0 and n.
    >>> list_even_integers(10)
    [0, 2, 4, 6, 8, 10]
    """
    if num < 0:
        return []

    even_integers = []
    for i in range(num + 1):
        if i % 2 == 0:
            even_integers.append(i)

    return even_integers


