def median(numbers: List[float]) -> float:
    """For a given list of input numbers, return the median.
    For a small (few) list of input numbers, use a simple scan of the list
    and find the middle value (the median). For larger list of input numbers,
    find the 50th percentile, which is equivalent to the median.

    >>> median([1, 2, 3, 4, 5])
    3.0
    >>> median([1, 3, 4, 5])
    3.5
    """
    n = len(numbers)
    if n == 0:
        return float("inf")

