def _find_max_nested_level(paren_string: str) -> int:
    """ Input is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.

    >>> _find_max_nested_level('(()()) ((())) () ((())()())')
    3
    """
    paren_groups = [paren for paren in paren_string.split() if len(paren) > 1]

    stack = [0]
    level = 0

    for each_group in paren_groups:
